"""Cold load and ordinary-input exploration; snapshots remain read-only."""
from pathlib import Path
import argparse,hashlib,json,math,sys,time
import numpy as np
from PIL import Image
from probe_base import ObservedRuntime,ROOT,HERE
from s760_runtime import RuntimeConfig

ap=argparse.ArgumentParser(description=__doc__)
ap.add_argument('--output',type=Path,required=True)
ap.add_argument('--source',type=Path)
ap.add_argument('--cold-performance',action='store_true')
a=ap.parse_args();work=a.output.resolve();work.mkdir(parents=True,exist_ok=False)
source=ROOT/'docs/ic20-hle-findings/chatGPT-work/bluescsi-feasibility-2026-10-18/stereo-04/captured-stereo.img'
if a.source: source=a.source.resolve()
cfg=RuntimeConfig(ROOT/'mame-source/mames760.exe',ROOT/'roms/BOOT/Roland_S-760_v1.11.BIN',ROOT/'roms/System/S760224.IMG',work/'runtime',source,sound=False,throttle=False,wave_dump=work/'wave.bin')
blank=ROOT/'docs/ic20-hle-findings/chatGPT-work/media-verification-20261012-065549/formatted.img'
if not a.cold_performance:
 (work/'command-000.json').write_text('[{"op": "click", "x": 70, "y": 5}, {"op": "click", "x": 80, "y": 30}, {"op": "shot", "name": "partial-empty"}, {"op": "dial", "x": 65, "y": 34, "delta": 1}, {"op": "shot", "name": "partial-left-only"}, {"op": "click", "x": 8, "y": 34}, {"op": "button", "port": ":PANEL0", "name": "S2"}, {"op": "shot", "name": "partial-stereo"}, {"op": "audio", "name": "partial-stereo"}, {"op": "click", "x": 40, "y": 5}, {"op": "click", "x": 65, "y": 30}, {"op": "dial", "x": 50, "y": 30, "delta": 1}, {"op": "shot", "name": "split-before-set"}, {"op": "click", "x": 76, "y": 98}, {"op": "shot", "name": "split-set"}, {"op": "audio", "name": "patch-stereo"}, {"op": "click", "x": 10, "y": 5}, {"op": "click", "x": 15, "y": 22}, {"op": "dial", "x": 65, "y": 30, "delta": 1}, {"op": "shot", "name": "performance-unnamed"}, {"op": "audio", "name": "performance-unnamed"}, {"op": "click", "x": 2, "y": 18}, {"op": "dial", "x": 80, "y": 34, "delta": 0}, {"op": "button", "port": ":NATIVE_MOUSE_BUTTONS", "name": "Mouse Right"}, {"op": "shot", "name": "performance-ascii"}, {"op": "click", "x": 66, "y": 70}, {"op": "click", "x": 38, "y": 66}, {"op": "click", "x": 22, "y": 58}, {"op": "click", "x": 98, "y": 62}, {"op": "click", "x": 42, "y": 62}, {"op": "click", "x": 50, "y": 62}, {"op": "click", "x": 54, "y": 66}, {"op": "click", "x": 132, "y": 66}, {"op": "click", "x": 80, "y": 34}, {"op": "shot", "name": "performance-named"}, {"op": "click", "x": 40, "y": 5}, {"op": "click", "x": 80, "y": 22}, {"op": "click", "x": 2, "y": 18}, {"op": "dial", "x": 80, "y": 34, "delta": 0}, {"op": "button", "port": ":NATIVE_MOUSE_BUTTONS", "name": "Mouse Right"}, {"op": "shot", "name": "patch-ascii"}, {"op": "click", "x": 132, "y": 66}, {"op": "click", "x": 80, "y": 34}, {"op": "shot", "name": "patch-named"}, {"op": "click", "x": 70, "y": 5}, {"op": "click", "x": 80, "y": 22}, {"op": "click", "x": 2, "y": 18}, {"op": "dial", "x": 80, "y": 34, "delta": 0}, {"op": "button", "port": ":NATIVE_MOUSE_BUTTONS", "name": "Mouse Right"}, {"op": "shot", "name": "partial-ascii"}, {"op": "click", "x": 132, "y": 66}, {"op": "click", "x": 80, "y": 34}, {"op": "shot", "name": "partial-named"}, {"op": "click", "x": 10, "y": 5}, {"op": "click", "x": 15, "y": 22}, {"op": "shot", "name": "performance-ready"}, {"op": "audio", "name": "performance-ready"}, {"op": "insert"}, {"op": "click", "x": 118, "y": 5}, {"op": "click", "x": 80, "y": 30}, {"op": "wait", "seconds": 5}, {"op": "click", "x": 20, "y": 22}, {"op": "click", "x": 25, "y": 42}, {"op": "wait", "seconds": 2}, {"op": "shot", "name": "save-list"}, {"op": "click", "x": 50, "y": 34}, {"op": "click", "x": 76, "y": 98}, {"op": "wait", "seconds": 3}, {"op": "shot", "name": "save-confirm-one"}, {"op": "click", "x": 62, "y": 70}, {"op": "wait", "seconds": 3}, {"op": "shot", "name": "save-confirm-two"}, {"op": "click", "x": 66, "y": 70}, {"op": "wait", "seconds": 50}, {"op": "shot", "name": "performance-saved"}, {"op": "export", "name": "saved-performance.img"}, {"op": "click", "x": 10, "y": 5}, {"op": "click", "x": 15, "y": 22}, {"op": "shot", "name": "after-save"}, {"op": "audio", "name": "after-save"}, {"op": "quit"}]',encoding='utf-8')
inputs=[blank,source,cfg.executable,cfg.boot_rom,cfg.system_disk,Path(__file__),HERE/'observer.lua',HERE/'probe_base.py']
hashes={str(p.relative_to(ROOT)):hashlib.sha256(p.read_bytes()).hexdigest() for p in inputs}
actions=[]
with ObservedRuntime(cfg) as rt:
 def wait(seconds):
  end=rt.request('status')[0]['seconds']+seconds;deadline=time.monotonic()+max(120,seconds*2)
  while rt.request('status')[0]['seconds']<end:
   assert time.monotonic()<deadline,'Native clock stopped'
   time.sleep(.01)
 def button(port,name):
  rt.request('button',port=port,name=name,down=True);wait(.12)
  rt.request('button',port=port,name=name,down=False);wait(.25)
 def click(x,y):
  rt.request('pointer',x=x,y=y);wait(.25);button(':NATIVE_MOUSE_BUTTONS','Mouse Left')
 def shot(name):
  assert name.replace('-','').replace('_','').isalnum()
  frames=rt.request('frames')
  Image.frombytes('RGBA',(640,480),frames[1][0][6:]).save(work/(name+'.png'))
  item=dict(name=name,snapshot=rt.snapshot_count,seconds=rt.request('status')[0]['seconds'])
  actions.append(item);print(json.dumps(item),flush=True)
 def render(frames):
  out=[]
  while frames:
   n=min(frames,8192);out.append(rt.render_audio(n)[1]);frames-=n
  return b''.join(out)
 wait(20);button(':NATIVE_MEDIA','Insert Sample Floppy')
 click(118,5);click(80,22);wait(8)
 if a.cold_performance:
  click(50,34);click(76,98);wait(65);shot('cold-loaded')
  click(10,5);click(15,22);wait(3);shot('perform-screen')
 else:
  click(20,22);wait(1);click(25,54);wait(2)
  click(10,98);click(76,98);wait(35);shot('cold-loaded')
  click(100,5);wait(1);click(80,26);wait(3);shot('loop-screen')
 (rt.observation_folder/'observe-objects.txt').write_text('enabled')
 rt.request('pause')
 print('READY',flush=True)
 request_id=0;deadline=time.monotonic()+1800
 while time.monotonic()<deadline:
  path=work/f'command-{request_id:03}.json'
  if not path.exists():time.sleep(.05);continue
  commands=json.loads(path.read_text())
  quit_requested=False
  for command in commands:
   op=command['op'];actions.append(dict(command=command))
   if op=='quit':quit_requested=True;break
   if op=='audio':
    name=command['name'];rt.request('pause');rt.request('audio_capture',enabled=True)
    rt.request('midi',bytes=[0x90,command.get('note',60),100]);pcm=render(65536)
    rt.request('midi',bytes=[0x80,command.get('note',60),0]);tail=render(88200)
    rt.request('audio_capture',enabled=False)
    (work/(name+'.pcm')).write_bytes(pcm);(work/(name+'-tail.pcm')).write_bytes(tail)
    v=np.frombuffer(pcm,dtype='<f4').reshape(-1,2)
    row=dict(audio=name,peaks=np.max(np.abs(v),axis=0).tolist(),rms=np.sqrt(np.mean(v*v,axis=0)).tolist(),sha256=hashlib.sha256(pcm).hexdigest())
    actions.append(row);print(json.dumps(row),flush=True)
   else:
    rt.request('resume')
    if op=='click':click(command['x'],command['y'])
    elif op=='wait':wait(command['seconds'])
    elif op=='button':button(command.get('port',':PANEL2'),command['name'])
    elif op=='dial':rt.request('pointer',x=command['x'],y=command['y']);wait(.3);rt.request('dial',id='ALPHA',delta=command['delta']);wait(1)
    elif op=='shot':shot(command['name'])
    elif op=='insert':rt.insert_media(blank)
    elif op=='export':rt.export_media(work/command['name'])
    elif op=='checkpoint':rt.save_checkpoint(work/command['name'])
    else:raise ValueError(op)
    rt.request('pause')
  (work/f'done-{request_id:03}.json').write_text(json.dumps(actions[-len(commands):]))
  request_id+=1
  if quit_requested:break
 else:raise TimeoutError('Exploration command deadline')
assert all(hashlib.sha256(p.read_bytes()).hexdigest()==hashes[str(p.relative_to(ROOT))] for p in inputs)
(work/'result.json').write_text(json.dumps(dict(actions=actions,identities=hashes,source_unchanged=True),indent=2)+'\n')
